import { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        email,
        password,
        role,
      });

      login(res.data);

      if (res.data.user.role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/dashboard');
      }
    } catch (err) {
      alert('Login failed: ' + (err.response?.data?.error || 'Invalid credentials'));
    }
  };

  return (
    <div
      style={{
        height: '100vh',
        background: '#0f172a',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        fontFamily: 'Poppins, sans-serif',
        overflow: 'hidden',
      }}
    >

      {/* Floating quiz icons (background feel) */}
      <div style={{
        position: 'absolute',
        color: '#ffffff10',
        fontSize: '120px',
        top: '10%',
        left: '10%',
      }}>?</div>

      <div style={{
        position: 'absolute',
        color: '#ffffff10',
        fontSize: '100px',
        bottom: '10%',
        right: '10%',
      }}>🧠</div>

      {/* Main Card */}
      <div
        style={{
          width: '400px',
          padding: '40px 30px',
          borderRadius: '20px',
          background: '#111827',
          boxShadow: '0 0 40px rgba(0,255,255,0.15)',
          position: 'relative',
        }}
      >

        {/* Logo + Title */}
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <img
            src="/logo.png"
            alt="logo"
            style={{
              width: '80px',
              borderRadius: '50%',
              marginBottom: '10px',
            }}
          />
          <h3 style={{ color: 'white', fontWeight: '600' }}>
            Quiz Portal
          </h3>
          <p style={{ color: '#9ca3af', fontSize: '13px' }}>
            Enter the challenge 🚀
          </p>
        </div>

        <form onSubmit={handleSubmit}>

          {/* Email */}
          <div style={{ marginBottom: '20px' }}>
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '10px',
                background: 'transparent',
                border: 'none',
                borderBottom: '2px solid #374151',
                color: 'white',
                outline: 'none',
              }}
            />
          </div>

          {/* Password */}
          <div style={{ marginBottom: '25px' }}>
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '10px',
                background: 'transparent',
                border: 'none',
                borderBottom: '2px solid #374151',
                color: 'white',
                outline: 'none',
              }}
            />
          </div>

          {/* Role Toggle */}
          <div style={{ marginBottom: '25px' }}>
            <p style={{ color: '#9ca3af', fontSize: '13px' }}>Select Role</p>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button
                type="button"
                onClick={() => setRole('student')}
                style={{
                  flex: 1,
                  padding: '10px',
                  borderRadius: '10px',
                  border: role === 'student' ? '2px solid #22c55e' : '1px solid #374151',
                  background: role === 'student' ? '#22c55e20' : 'transparent',
                  color: 'white',
                }}
              >
                🎓 Student
              </button>

              <button
                type="button"
                onClick={() => setRole('admin')}
                style={{
                  flex: 1,
                  padding: '10px',
                  borderRadius: '10px',
                  border: role === 'admin' ? '2px solid #3b82f6' : '1px solid #374151',
                  background: role === 'admin' ? '#3b82f620' : 'transparent',
                  color: 'white',
                }}
              >
                🛠 Admin
              </button>
            </div>
          </div>

          {/* Login Button */}
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '12px',
              borderRadius: '12px',
              border: 'none',
              background: 'linear-gradient(90deg, #06b6d4, #3b82f6)',
              color: 'white',
              fontWeight: '600',
              letterSpacing: '1px',
              transition: '0.3s',
            }}
          >
            Start Quiz →
          </button>

        </form>

        {/* Footer */}
        <div style={{ textAlign: 'center', marginTop: '20px' }}>
          <span style={{ color: '#9ca3af', fontSize: '13px' }}>
            New here?{' '}
            <a href="/register" style={{ color: '#22c55e' }}>
              Join Now
            </a>
          </span>
        </div>

      </div>
    </div>
  );
}
